import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

const validatorOptions = {strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0];
const schemaValidator = new Ajv(validatorOptions);

function validationSchema(schema: object): object {
  const source = schema as Record<string, unknown>;
  const projected: Record<string, unknown> = {};
  for (const keyword of ['type', 'enum', 'required'] as const) {
    if (keyword in source) projected[keyword] = source[keyword];
  }
  if (source.properties && typeof source.properties === 'object') {
    projected.properties = Object.fromEntries(
      Object.entries(source.properties).map(([name, child]) => [
        name,
        child && typeof child === 'object' ? validationSchema(child) : child,
      ])
    );
  }
  if (source.items && typeof source.items === 'object') projected.items = validationSchema(source.items);
  return projected;
}

function schemaRejection(errors: unknown[]): ToolResponse {
  const error = errors[0];
  const keyword = errorProperty(error, 'keyword');
  const params = errorProperty(error, 'params');
  const missingProperty = errorProperty(params, 'missingProperty');
  const expectedType = errorProperty(params, 'type');
  const instancePath = errorProperty(error, 'instancePath');
  const propertyPath =
    typeof missingProperty === 'string'
      ? `${typeof instancePath === 'string' ? instancePath : ''}/${missingProperty.replace(/~/g, '~0').replace(/\//g, '~1')}`
      : (typeof instancePath === 'string' && instancePath) || 'input';
  const issue =
    keyword === 'required'
      ? 'is required'
      : keyword === 'type' && typeof expectedType === 'string'
        ? `must be a ${expectedType}`
        : `must satisfy ${String(keyword)}`;
  return {result: `Invalid input at ${propertyPath}: ${issue}.`};
}

function errorProperty(error: unknown, property: string): unknown {
  if (typeof error !== 'object' || error === null || !(property in error)) return undefined;
  return (error as Record<string, unknown>)[property];
}

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const staticValidator =
      typeof definition === 'function' ? undefined : this.compileSchema(resolved.inputSchema, resolved.name);
    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
  }

  private compileSchema(schema: object, name: string): ValidateFunction {
    try {
      return schemaValidator.compile(validationSchema(schema));
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool ${name}: ${message}`, {cause: error});
    }
  }

  private dynamicValidator(schema: object, name: string): ValidateFunction {
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const validator = this.compileSchema(schema, name);
    this.dynamicValidators.set(schema, validator);
    return validator;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

